/**
 * @description Monitor tab (admins only): totals by status and direction, failures grouped by event and error,
 * and retry of a group or chosen transactions. The connection and endpoint checks are in IntegrationHubEndpointCheck.
 * @group Integration Hub
 */
public with sharing class IntegrationHubMonitorController {
    /** Tests set this: a custom permission given through a permission set in a test is not always visible to checkPermission. */
    @TestVisible
    private static Boolean adminInTest = false;

    private static final Integer DIRECT_LIMIT = 200;
    /** Each status or direction count stops here, so a long period stays within the 50,000 query-row limit. */
    @TestVisible
    private static final Integer COUNT_CAP = 4000;
    /** Failure groups are built from this many of the latest failures. */
    @TestVisible
    private static final Integer GROUP_SAMPLE = 2000;
    private static final String PERIOD = 'CreatedDate >= :fromDt AND CreatedDate < :toDt';
    private static final String GROUP_FILTER = 'Direction__c = :dir AND Status__c IN :bad AND ' + PERIOD
        + ' AND Event_Name__c = :eventName AND Error_Summary__c = :errorSummary';

    /**
     * @description Count of transactions with one status and direction.
     */
    public class CountRow {
        /** @description Status. */
        @AuraEnabled public String status;
        /** @description Direction. */
        @AuraEnabled public String direction;
        /** @description Number of transactions. */
        @AuraEnabled public Integer total;
        /** @description True when the count reached the cap: there are at least this many. */
        @AuraEnabled public Boolean capped = false;
    }

    /**
     * @description Failed or Abandoned transactions with the same event and error.
     */
    public class GroupRow implements Comparable {
        /** @description Event key. */
        @AuraEnabled public String eventName;
        /** @description Error summary (may be null). */
        @AuraEnabled public String errorSummary;
        /** @description Number of transactions. */
        @AuraEnabled public Integer total;
        /** @description Latest change. */
        @AuraEnabled public Datetime latest;

        /**
         * @description Largest group first.
         * @param other another group
         * @return the sort order
         */
        public Integer compareTo(Object other) {
            return ((GroupRow) other).total - total;
        }
    }

    /**
     * @description One failure group in a period, as the Monitor sends it for Retry group.
     */
    public class GroupRequest {
        /** @description Event key. */
        @AuraEnabled public String eventName { get; set; }
        /** @description Error summary (null matches an empty summary). */
        @AuraEnabled public String errorSummary { get; set; }
        /** @description First day of the period, or null. */
        @AuraEnabled public Date fromDate { get; set; }
        /** @description Last day of the period, or null. */
        @AuraEnabled public Date toDate { get; set; }
    }

    /**
     * @description Monitor data.
     */
    public class Summary {
        /** @description Totals by status and direction. */
        @AuraEnabled public List<CountRow> counts = new List<CountRow>();
        /** @description Failure groups, largest first (top 50). */
        @AuraEnabled public List<GroupRow> groups = new List<GroupRow>();
        /** @description How many failures the groups were built from (at most GROUP_SAMPLE, the latest ones). */
        @AuraEnabled public Integer groupedFrom = 0;
        /** @description True when there were more failures than were grouped. */
        @AuraEnabled public Boolean groupsSampled = false;
    }

    /**
     * @description Totals by status and direction, and failure groups, for a period. Blank dates mean open-ended,
     * so both blank is all time. Each count stops at COUNT_CAP and the groups use the latest GROUP_SAMPLE failures,
     * so any period stays within the query-row limit.
     * @param fromDate first day (inclusive), or null
     * @param toDate last day (inclusive), or null
     * @return the summary
     */
    @AuraEnabled
    public static Summary getSummary(Date fromDate, Date toDate) {
        requireAdmin();
        Map<String, Object> binds = periodBinds(fromDate, toDate);
        Summary s = new Summary();
        for (String st : new List<String>{ IntegrationHub.STATUS_PENDING, IntegrationHub.STATUS_RECEIVED, IntegrationHub.STATUS_SENT,
                IntegrationHub.STATUS_SUCCESS, IntegrationHub.STATUS_RETRY, IntegrationHub.STATUS_FAILED, IntegrationHub.STATUS_ABANDONED }) {
            s.counts.add(countRow('Status__c', st, binds));
        }
        s.counts.add(countRow('Direction__c', IntegrationHub.OUTBOUND, binds));
        s.counts.add(countRow('Direction__c', IntegrationHub.INBOUND, binds));
        addGroups(s, binds);
        return s;
    }

    private static CountRow countRow(String field, String value, Map<String, Object> binds) {
        Map<String, Object> b = new Map<String, Object>(binds);
        b.put('val', value);
        CountRow c = new CountRow();
        if (field == 'Status__c') {
            c.status = value;
        } else {
            c.direction = value;
        }
        c.total = IntegrationHubData.countQuery('SELECT COUNT() FROM IH_Transaction__c WHERE ' + field + ' = :val AND ' + PERIOD
            + ' LIMIT ' + COUNT_CAP, b);
        c.capped = c.total >= COUNT_CAP;
        return c;
    }

    private static void addGroups(Summary s, Map<String, Object> binds) {
        Map<String, Object> b = new Map<String, Object>(binds);
        b.put('bad', IntegrationHubMaintenance.badStatuses());
        Map<String, GroupRow> byKey = new Map<String, GroupRow>();
        List<SObject> rows = IntegrationHubData.query('SELECT Event_Name__c, Error_Summary__c, LastModifiedDate FROM IH_Transaction__c '
            + 'WHERE Status__c IN :bad AND ' + PERIOD + ' ORDER BY LastModifiedDate DESC LIMIT ' + GROUP_SAMPLE, b);
        for (SObject row : rows) {
            IH_Transaction__c t = (IH_Transaction__c) row;
            String key = t.Event_Name__c + '\n' + t.Error_Summary__c;
            GroupRow g = byKey.get(key);
            if (g == null) {
                g = new GroupRow();
                g.eventName = t.Event_Name__c;
                g.errorSummary = t.Error_Summary__c;
                g.total = 0;
                g.latest = t.LastModifiedDate;
                byKey.put(key, g);
            }
            g.total++;
        }
        List<GroupRow> groups = byKey.values();
        groups.sort();
        for (Integer i = 0; i < Math.min(groups.size(), 50); i++) {
            s.groups.add(groups[i]);
        }
        s.groupedFrom = rows.size();
        s.groupsSampled = rows.size() >= GROUP_SAMPLE;
    }

    /**
     * @description Retries the outbound Failed and Abandoned transactions of one group. Up to 200 are sent at once;
     * more are marked by a batch whose chunks are sent by the transaction trigger.
     * @param request the group and the period
     * @return the number of transactions retried
     */
    @AuraEnabled
    public static Integer retryGroup(GroupRequest request) {
        requireAdmin();
        Map<String, Object> binds = groupBinds(request == null ? new GroupRequest() : request);
        Integer total = IntegrationHubData.countQuery('SELECT COUNT() FROM IH_Transaction__c WHERE ' + GROUP_FILTER, binds);
        if (total > DIRECT_LIMIT) {
            IntegrationHubMaintenance.retryInBackground(GROUP_FILTER, binds);
            return total;
        }
        List<Id> ids = new List<Id>(new Map<Id, SObject>(IntegrationHubData.query(
            'SELECT Id FROM IH_Transaction__c WHERE ' + GROUP_FILTER + ' LIMIT 200', binds)).keySet());
        return IntegrationHubMaintenance.retryNow(ids);
    }

    /**
     * @description Retries chosen outbound Failed or Abandoned transactions now.
     * @param ids the transactions
     * @return the number retried
     */
    @AuraEnabled
    public static Integer retryIds(List<Id> ids) {
        requireAdmin();
        return ids == null || ids.isEmpty() ? 0 : IntegrationHubMaintenance.retryNow(ids);
    }

    /**
     * @description The period as bind values fromDt and toDt (user's time zone; the last day is included).
     * Blank dates are open-ended.
     * @param fromDate first day, or null
     * @param toDate last day, or null
     * @return the binds
     */
    @TestVisible
    private static Map<String, Object> periodBinds(Date fromDate, Date toDate) {
        Time midnight = Time.newInstance(0, 0, 0, 0);
        return new Map<String, Object>{
            'fromDt' => fromDate == null ? Datetime.newInstanceGmt(2000, 1, 1) : Datetime.newInstance(fromDate, midnight),
            'toDt' => toDate == null ? System.now().addDays(1) : Datetime.newInstance(toDate.addDays(1), midnight)
        };
    }

    /**
     * @description Bind values of one failure group (outbound, Failed or Abandoned, in the period).
     * @param request the group and the period
     * @return the binds for GROUP_FILTER
     */
    @TestVisible
    private static Map<String, Object> groupBinds(GroupRequest request) {
        Map<String, Object> binds = periodBinds(request.fromDate, request.toDate);
        binds.put('dir', IntegrationHub.OUTBOUND);
        binds.put('bad', IntegrationHubMaintenance.badStatuses());
        binds.put('eventName', request.eventName);
        binds.put('errorSummary', request.errorSummary);
        return binds;
    }

    /**
     * @description Stops the call unless the user has the Integration Hub Admin permission.
     */
    public static void requireAdmin() {
        if (!adminInTest && !FeatureManagement.checkPermission('Integration_Hub_Admin')) {
            AuraHandledException e = new AuraHandledException('Integration Hub Admin permission is required.');
            e.setMessage('Integration Hub Admin permission is required.');
            throw e;
        }
    }
}
